// Tip against fare, one dot per trip paid with a tip in the last half hour,
// and a brush over the fare that filters the maps.
//
// Dragging across the chart writes the fare range, in whole dollars, to two
// dashboard variables (LO and HI): the trip-by-trip arcs and the flows keep
// only the trips whose fare is inside it. The chart does not filter itself:
// dots outside the range stay, faded. A click without a drag clears it.
// The query frame has columns `Fare` and `Tip`, in dollars.
// @constants begin
const LO = 'fare_lo';
const HI = 'fare_hi';
const STEP = 1;
const DOMAIN = [0, 70];
const UNIT = 'fare ($)';
const COLOR = '#35c6dc';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const fares = col('Fare').map(Number);
const tips = col('Tip').map(Number);
const points = fares.map((f, i) => [f, tips[i]]);

// Whole dollars only, and never an empty range.
const snap = (range) => {
  const lo = Math.max(DOMAIN[0], Math.floor(range[0] / STEP) * STEP);
  const hi = Math.min(DOMAIN[1], Math.max(Math.ceil(range[1] / STEP) * STEP, lo + STEP));
  return [lo, hi];
};
const drawBrush = (range) =>
  chart.dispatchAction({ type: 'brush', areas: range ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: range }] : [] });
const publish = (range) => {
  location.partial({ ['var-' + LO]: range ? String(range[0]) : '', ['var-' + HI]: range ? String(range[1]) : '' }, true);
};

// The drag is handled here, on the chart's zrender, not by ECharts' own brush:
// this dashboard refreshes every 5 s, and a refresh that lands during a drag
// redraws the chart and drops an ECharts brush before it ends. The zrender
// outlives redraws, so the drag carries on across them; the brush component
// only draws the range. A click without a drag clears it.
const zr = chart.getZr();
const fareAt = (x) => Math.max(DOMAIN[0], Math.min(DOMAIN[1], chart.convertFromPixel({ xAxisIndex: 0 }, x)));
for (const [name, fn] of Object.entries(chart.__fareDrag || {})) {
  zr.off(name, fn);
}
chart.__fareDrag = {
  mousedown: (e) => {
    if (chart.containPixel('grid', [e.offsetX, e.offsetY])) {
      chart.__drag = { x: e.offsetX, fare: fareAt(e.offsetX) };
    }
  },
  mousemove: (e) => {
    const d = chart.__drag;
    if (d && Math.abs(e.offsetX - d.x) > 3) {
      const f = fareAt(e.offsetX);
      drawBrush([Math.min(d.fare, f), Math.max(d.fare, f)]);
    }
  },
  mouseup: (e) => {
    const d = chart.__drag;
    chart.__drag = null;
    if (!d) return;
    if (Math.abs(e.offsetX - d.x) <= 3) {
      drawBrush(null);
      publish(undefined);
      return;
    }
    const f = fareAt(e.offsetX);
    const range = snap([Math.min(d.fare, f), Math.max(d.fare, f)]);
    drawBrush(range);
    publish(range);
  },
};
for (const [name, fn] of Object.entries(chart.__fareDrag)) {
  zr.on(name, fn);
}

// Every redraw wipes the brush: draw it back from the variables, which is
// also how a shared link arrives with its range.
const current = [
  parseFloat(context.grafana.replaceVariables('${' + LO + '}')),
  parseFloat(context.grafana.replaceVariables('${' + HI + '}')),
];
const picked = current.every(Number.isFinite);
const inRange = picked ? points.filter((p) => p[0] >= current[0] && p[0] < current[1]).length : null;
setTimeout(() => drawBrush(picked ? current : null), 0);

const muted = theme.colors.text.secondary;

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 22, right: 16, top: 28, bottom: 22, containLabel: true },
  // The brush only draws the range: no toolbox, the drag is handled above.
  toolbox: { show: false },
  title: {
    show: true,
    text: picked
      ? `$${current[0]}–$${current[1]}: ${inRange} of ${points.length} trips · click to clear`
      : 'Drag across to pick a fare range',
    left: 4,
    top: 2,
    textStyle: { color: muted, fontSize: 11, fontWeight: 'normal' },
  },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const [f, t] = p.value;
      return `Fare <b>$${f.toFixed(2)}</b><br/>Tip <b>$${t.toFixed(2)}</b> (${Math.round((100 * t) / f)} %)`;
    },
  },
  brush: {
    xAxisIndex: 0,
    seriesIndex: [0],
    brushType: 'lineX',
    brushMode: 'single',
    transformable: false,
    brushStyle: { color: 'rgba(128, 128, 128, 0.12)', borderColor: muted, borderWidth: 1 },
    outOfBrush: { colorAlpha: 0.15 },
  },
  xAxis: {
    type: 'value',
    min: DOMAIN[0],
    max: DOMAIN[1],
    name: UNIT,
    nameLocation: 'middle',
    nameGap: 24,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, formatter: (v) => `$${v}` },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    name: 'tip ($)',
    nameLocation: 'middle',
    nameGap: 36,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, formatter: (v) => `$${v}` },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series: [
    {
      name: 'Trips',
      type: 'scatter',
      data: points,
      symbolSize: 4,
      itemStyle: { color: COLOR, opacity: 0.55 },
      emphasis: { disabled: true },
    },
  ],
};

